import{_ as t,o as n,c as a,a4 as o}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse(`{"title":"FAQ","description":"Frequently asked questions about Tokeness Base URL, API keys, model names, billing, balance, and tool integrations.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Tokeness Base URL, API keys, model names, billing, balance, and tool integrations.","head":[["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@type\\": \\"FAQPage\\",\\n  \\"mainEntity\\": [\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What is Tokeness?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Tokeness is an AI API gateway. You use one API key to call different models and review balance, logs, and usage in the console.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What Base URL should I use?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"For OpenAI-compatible integration, use https://n.tokeness.dev/v1. Do not remove /v1 yourself.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Why does authentication fail?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Common causes include an incompletely copied key, missing Bearer in the request header, a disabled key, or an environment variable that has not taken effect.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Are Claude Max and the Claude API the same thing?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"No. Claude Max is a subscription plan for individual use. The Claude API uses an API key to call models, and the model name or ID is determined by the API provider's console or model marketplace. A subscription plan name is not an API model ID and does not prove which model handled a request.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"How should I troubleshoot 401, 429, or 5xx responses?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"For 401, check the API key, Base URL, model name, protocol type, and Authorization: Bearer header. For 429, check key limits, wallet balance, and request frequency, then reduce concurrency or retry later. For 5xx, record the time, request path, model name, and status, review usage logs, avoid repeated retries, and provide those details to support if the same configuration still fails.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What should I do if a streaming response is interrupted?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"First confirm that a non-streaming request succeeds. Then check the client timeout, network connection, proxy, and stream-reading implementation. Record the status, request path, and model name before the interruption, fix the connection or timeout settings, and retry with a small request. An interruption alone does not prove model identity or availability.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Why does a request show insufficient balance?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Tokeness uses a prepaid model. Check your wallet balance and whether the current API key has a quota limit.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Where should model names be copied from?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Copy from the Tokeness console or model marketplace. Model names must keep their exact case, hyphens, and version numbers.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Can I share one API key?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Technically yes. Using separate keys for development, production, customer projects, and automation tasks makes it easier to set limits and troubleshoot.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Which tools are supported?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Tools that support a custom OpenAI-compatible Base URL can be connected using this documentation. Configuration references are provided for Cherry Studio, Claude Code, VS Code Claude Code plugin, Cline, Roo Code, Continue, Cursor, Codex CLI, Dify, n8n, Open WebUI, AnythingLLM, LibreChat, LiteLLM, OpenClaw, and OpenCode.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What if the Claude Code command is not found after installation?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"First confirm Node.js and npm are installed, then restart the terminal. On Windows, use PowerShell, WSL2, or the shell environment recommended by the tool.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What to do when connecting AI coding tools returns 401?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Check the API key, Base URL, model name, and protocol type in the tool configuration. For OpenAI-compatible integration, use https://n.tokeness.dev/v1 and the header Authorization: Bearer <API Key>.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What is YOUR_MODEL_NAME in the code examples?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"It is not a fixed model name. Copy the actual model name from the model marketplace and replace it.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"Which AI models does Tokeness support?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Tokeness supports a variety of mainstream models. Available model names are authoritative in the Tokeness console or model marketplace.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"How is Tokeness different from calling OpenAI directly?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Tokeness is a gateway compatible with the OpenAI API format. It lets you access multiple models with the same code and centrally manage API keys, quotas, and usage logs.\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"How do I use Tokeness in Claude Code?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Claude Code natively uses the Anthropic protocol. The Tokeness universal interface uses the OpenAI-compatible protocol, so it is recommended to add Tokeness as a provider via CC Switch and enable routing mode. Set the Base URL to https://n.tokeness.dev (without /v1 — CC Switch appends the path itself).\\"\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"Question\\",\\n      \\"name\\": \\"What top-up methods are supported?\\",\\n      \\"acceptedAnswer\\": {\\n        \\"@type\\": \\"Answer\\",\\n        \\"text\\": \\"Top-up methods are authoritative on the console Wallet page. After entering the console, open Wallet to view currently available top-up channels, balance, and top-up records.\\"\\n      }\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1784332800000}`),s={name:"faq.md"};function i(r,e,d,l,h,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Tokeness is an AI API gateway for calling available models through documented API formats and reviewing keys, balance, and usage in the console. This FAQ covers Tokeness configuration and troubleshooting; it does not rank third-party services, compare Claude model quality, or guarantee pricing, availability, latency, or savings.</p><h2 id="what-is-tokeness" tabindex="-1">What is Tokeness? <a class="header-anchor" href="#what-is-tokeness" aria-label="Permalink to &quot;What is Tokeness?&quot;">​</a></h2><p>Tokeness is an AI API gateway. You use one API key to call different models and review balance, logs, and usage in the console.</p><h2 id="what-base-url-should-i-use" tabindex="-1">What Base URL should I use? <a class="header-anchor" href="#what-base-url-should-i-use" aria-label="Permalink to &quot;What Base URL should I use?&quot;">​</a></h2><p>Use the same address on every integration page:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.dev/v1</span></span></code></pre></div><p>If a client splits the field into Base URL, Endpoint, Host, or Service URL, put this complete address in the field that accepts a full path. Do not remove <code>/v1</code> yourself.</p><h2 id="why-does-authentication-fail" tabindex="-1">Why does authentication fail? <a class="header-anchor" href="#why-does-authentication-fail" aria-label="Permalink to &quot;Why does authentication fail?&quot;">​</a></h2><p>Common causes include an incompletely copied key, missing <code>Bearer</code> in the request header, a disabled key, or an environment variable that has not taken effect.</p><h2 id="are-claude-max-and-the-claude-api-the-same-thing" tabindex="-1">Are Claude Max and the Claude API the same thing? <a class="header-anchor" href="#are-claude-max-and-the-claude-api-the-same-thing" aria-label="Permalink to &quot;Are Claude Max and the Claude API the same thing?&quot;">​</a></h2><p>No. Claude Max is a subscription plan for individual use. The Claude API uses an API key to call models, and the model name or model ID is determined by the API provider&#39;s console or model marketplace. A subscription plan name is not an API model ID and does not prove which model handled a request.</p><h2 id="how-should-i-troubleshoot-401-429-or-5xx-responses" tabindex="-1">How should I troubleshoot 401, 429, or 5xx responses? <a class="header-anchor" href="#how-should-i-troubleshoot-401-429-or-5xx-responses" aria-label="Permalink to &quot;How should I troubleshoot 401, 429, or 5xx responses?&quot;">​</a></h2><p>Use the following order while keeping the request details:</p><ol><li><strong>401</strong>: Check whether the API key is complete and enabled. Then check the Base URL, model name, protocol type, and whether an OpenAI-compatible request includes <code>Authorization: Bearer &lt;API Key&gt;</code>.</li><li><strong>429</strong>: Check the key limit, wallet balance, and request frequency. Reduce concurrency or retry later, and use usage logs to check whether a request was charged more than once.</li><li><strong>5xx</strong>: Record the time, request path, model name, and response status. Review the error in usage logs, avoid repeated retries, and retry later with the same configuration. If it still fails, provide those details to support.</li></ol><h2 id="what-should-i-do-if-a-streaming-response-is-interrupted" tabindex="-1">What should I do if a streaming response is interrupted? <a class="header-anchor" href="#what-should-i-do-if-a-streaming-response-is-interrupted" aria-label="Permalink to &quot;What should I do if a streaming response is interrupted?&quot;">​</a></h2><p>First confirm that a non-streaming request succeeds. Then check the client timeout, network connection, proxy, and stream-reading implementation. Record the status, request path, and model name before the interruption, fix the connection or timeout settings, and retry with a small request. An interruption alone does not prove model identity or availability.</p><h2 id="why-does-a-request-show-insufficient-balance" tabindex="-1">Why does a request show insufficient balance? <a class="header-anchor" href="#why-does-a-request-show-insufficient-balance" aria-label="Permalink to &quot;Why does a request show insufficient balance?&quot;">​</a></h2><p>Tokeness uses a prepaid model. Check your wallet balance and whether the current API key has a quota limit.</p><h2 id="where-should-model-names-be-copied-from" tabindex="-1">Where should model names be copied from? <a class="header-anchor" href="#where-should-model-names-be-copied-from" aria-label="Permalink to &quot;Where should model names be copied from?&quot;">​</a></h2><p>Copy from the Tokeness console or model marketplace. Model names must keep their exact case, hyphens, and version numbers.</p><p>When connecting for the first time, copy one available model name, then go back to the tutorial and replace <code>YOUR_MODEL_NAME</code>.</p><h2 id="can-i-share-one-api-key" tabindex="-1">Can I share one API key? <a class="header-anchor" href="#can-i-share-one-api-key" aria-label="Permalink to &quot;Can I share one API key?&quot;">​</a></h2><p>Technically yes. Using separate keys for development, production, customer projects, and automation tasks makes it easier to set limits and troubleshoot.</p><h2 id="which-tools-are-supported" tabindex="-1">Which tools are supported? <a class="header-anchor" href="#which-tools-are-supported" aria-label="Permalink to &quot;Which tools are supported?&quot;">​</a></h2><p>Tools that support a custom OpenAI-compatible Base URL can be connected using this documentation. Configuration references are provided for Cherry Studio, Claude Code, VS Code Claude Code plugin, Cline, Roo Code, Continue, Cursor, Codex CLI, Dify, n8n, Open WebUI, AnythingLLM, LibreChat, LiteLLM, OpenClaw, and OpenCode.</p><h2 id="what-if-the-claude-code-command-is-not-found-after-installation" tabindex="-1">What if the Claude Code command is not found after installation? <a class="header-anchor" href="#what-if-the-claude-code-command-is-not-found-after-installation" aria-label="Permalink to &quot;What if the Claude Code command is not found after installation?&quot;">​</a></h2><p>First confirm Node.js and npm are installed, then restart the terminal. On Windows, use PowerShell, WSL2, or the shell environment recommended by the tool.</p><h2 id="what-to-do-when-connecting-ai-coding-tools-returns-401" tabindex="-1">What to do when connecting AI coding tools returns 401? <a class="header-anchor" href="#what-to-do-when-connecting-ai-coding-tools-returns-401" aria-label="Permalink to &quot;What to do when connecting AI coding tools returns 401?&quot;">​</a></h2><p>Check the API key, Base URL, model name, and protocol type in the tool configuration. For OpenAI-compatible integration, use <code>https://n.tokeness.dev/v1</code> and the header <code>Authorization: Bearer &lt;API Key&gt;</code>.</p><h2 id="what-is-your-model-name-in-the-code-examples" tabindex="-1">What is <code>YOUR_MODEL_NAME</code> in the code examples? <a class="header-anchor" href="#what-is-your-model-name-in-the-code-examples" aria-label="Permalink to &quot;What is `YOUR_MODEL_NAME` in the code examples?&quot;">​</a></h2><p>It is not a fixed model name. Copy the actual model name from the model marketplace and replace it.</p><h2 id="which-ai-models-does-tokeness-support" tabindex="-1">Which AI models does Tokeness support? <a class="header-anchor" href="#which-ai-models-does-tokeness-support" aria-label="Permalink to &quot;Which AI models does Tokeness support?&quot;">​</a></h2><p>Tokeness supports a variety of mainstream models. Available model names are authoritative in the Tokeness console or model marketplace. Before use, copy the full model name from the model marketplace; do not substitute default model names from other platforms or tools.</p><h2 id="how-is-tokeness-different-from-calling-openai-directly" tabindex="-1">How is Tokeness different from calling OpenAI directly? <a class="header-anchor" href="#how-is-tokeness-different-from-calling-openai-directly" aria-label="Permalink to &quot;How is Tokeness different from calling OpenAI directly?&quot;">​</a></h2><p>Tokeness is a gateway compatible with the OpenAI API format. When connecting OpenAI-compatible tools, you typically only need to replace <code>base_url</code> and <code>api_key</code>; business code continues to call the OpenAI-compatible format. Tokeness also provides centralized key management, quota control, usage logs, and multi-model access.</p><h2 id="how-do-i-use-tokeness-in-claude-code" tabindex="-1">How do I use Tokeness in Claude Code? <a class="header-anchor" href="#how-do-i-use-tokeness-in-claude-code" aria-label="Permalink to &quot;How do I use Tokeness in Claude Code?&quot;">​</a></h2><p>Claude Code natively uses the Anthropic protocol. The Tokeness universal interface uses the OpenAI-compatible protocol, so it is recommended to add Tokeness as a provider via CC Switch and enable routing mode to handle protocol conversion. See the <a href="/integrations/claude-code">Claude Code integration guide</a>.</p><h2 id="what-top-up-methods-are-supported" tabindex="-1">What top-up methods are supported? <a class="header-anchor" href="#what-top-up-methods-are-supported" aria-label="Permalink to &quot;What top-up methods are supported?&quot;">​</a></h2><p>Top-up methods are authoritative on the console Wallet page. After entering the console, open Wallet to view currently available top-up channels, balance, and top-up records.</p>',40)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
